export const paradisBehaviors="document.querySelectorAll('[data-current-year]').forEach(element=>{element.textContent=String(new Date().getFullYear())});\nconst menuButton=document.querySelector('.menu-toggle');\nmenuButton?.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));document.querySelector('#site-nav').classList.toggle('is-open',open)});\ndocument.querySelectorAll('.thrv_toggle_item').forEach((item,i)=>{const title=item.querySelector('.thrv_toggle_title'),answer=item.querySelector('.tve_faqC');if(!title||!answer)return;answer.id='faq-answer-'+i;title.setAttribute('role','button');title.tabIndex=0;title.setAttribute('aria-controls',answer.id);title.setAttribute('aria-expanded','false');const toggle=()=>{const open=item.classList.toggle('is-open');title.setAttribute('aria-expanded',String(open))};title.addEventListener('click',toggle);title.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}})});\n";
